shared_html.shared_css:
/* ============ SHARED HEADER / FOOTER ============ */

.site-nav,
.site-footer {
  font-family: "Cormorant Garamond", Georgia, serif;
  color: var(--text);
  background: var(--surface);
  position: relative;
}

/* ---- HEADER ---- */

.site-nav {
  padding: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--ornament) 35%, transparent);
}

.site-nav__rule {
  height: 6px;
  background:
    linear-gradient(90deg,
      transparent 0%,
      var(--ornament) 8%,
      var(--ornament) 92%,
      transparent 100%);
  opacity: 0.55;
}

.site-nav__rule--bottom {
  height: 2px;
  opacity: 0.35;
}

.site-nav__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 1.4rem 2rem 1.6rem;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1.5rem;
  text-align: center;
}

.site-nav__kicker {
  justify-self: start;
  font-family: "Cinzel Decorative", serif;
  font-size: 0.7rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--primary);
  opacity: 0.85;
}

.site-nav__wordmark {
  justify-self: center;
  text-decoration: none;
  color: var(--text-emphasis);
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1;
  gap: 0.3rem;
}

.site-nav__wordmark-line1 {
  font-family: "Cinzel Decorative", serif;
  font-weight: 900;
  font-size: 1.55rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary);
}

.site-nav__wordmark-ornament {
  color: var(--secondary);
  font-size: 0.8rem;
}

.site-nav__wordmark-line2 {
  font-family: "Cormorant Garamond", serif;
  font-style: italic;
  font-size: 0.95rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
  opacity: 0.85;
}

.site-nav__menu {
  justify-self: end;
}

.site-nav__menu ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 1.6rem;
}

.site-nav__menu a {
  font-family: "Cinzel Decorative", serif;
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
  text-decoration: none;
  padding: 0.4rem 0;
  border-bottom: 1px solid transparent;
  transition: color 0.25s, border-color 0.25s;
}

.site-nav__menu a:hover,
.site-nav__menu a:focus {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

@media (max-width: 900px) {
  .site-nav__inner {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .site-nav__kicker,
  .site-nav__menu {
    justify-self: center;
  }
  .site-nav__menu ul {
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.8rem 1.2rem;
  }
}

/* ---- FOOTER ---- */

.site-footer {
  margin-top: 4rem;
  padding-top: 0;
  background: var(--surface);
  border-top: 1px solid color-mix(in srgb, var(--ornament) 35%, transparent);
}

.site-footer__rule {
  height: 6px;
  background:
    linear-gradient(90deg,
      transparent 0%,
      var(--ornament) 8%,
      var(--ornament) 92%,
      transparent 100%);
  opacity: 0.55;
}

.site-footer__seal {
  width: 84px;
  height: 84px;
  margin: 2rem auto 0.5rem;
  color: var(--primary);
  display: block;
  /* one looped animation: seal-breathe */
  animation: seal-breathe 3s ease-in-out infinite;
}

@keyframes seal-breathe {
  0%, 100% { transform: scale(1); opacity: 0.85; }
  50%      { transform: scale(1.18); opacity: 1; }
}

.site-footer__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 1.5rem 2rem 2.5rem;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  text-align: center;
}

.site-footer__col h4 {
  font-family: "Cinzel Decorative", serif;
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--primary);
  margin: 0 0 1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid color-mix(in srgb, var(--ornament) 40%, transparent);
}

.site-footer__col p {
  margin: 0 0 0.8rem;
  font-size: 1rem;
  line-height: 1.65;
  color: var(--accent);
}

.site-footer__col--nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.site-footer__col--nav a {
  font-family: "Cormorant Garamond", serif;
  font-size: 1rem;
  letter-spacing: 0.04em;
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: color 0.25s, border-color 0.25s;
}

.site-footer__col--nav a:hover,
.site-footer__col--nav a:focus {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.site-footer__colophon {
  max-width: 1240px;
  margin: 0 auto;
  padding: 1.4rem 2rem 2rem;
  border-top: 1px solid color-mix(in srgb, var(--ornament) 25%, transparent);
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.9rem;
  font-family: "Cinzel Decorative", serif;
  font-size: 0.7rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
  opacity: 0.8;
  text-align: center;
}

.site-footer__diamond {
  color: var(--primary);
}

@media (max-width: 900px) {
  .site-footer__inner {
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
  }
}

@media (max-width: 560px) {
  .site-footer__inner {
    grid-template-columns: 1fr;
  }
}
